@startuml

class OilCompany {}

class GasStation {
  + Name : string
}

class Pump {
  + Type : string
  + RefillThreshold : double
  + CriticalLevel : double
  + CurrentLevel : double
  + QuantityToOrder : double
  + IsBlocked : boolean
}

class Reservoir {
  + Quantity : double
}

class RefuelTurn {
  + Amount : double
}

class CashTurn {}

class CreditCardTurn {}

class FuelCard {
  + IsBlocked : boolean
}

class Customer {
  + Name : string
  + IsSuspended : boolean
  + Turnover : double
}

class Invoice {
  + Month : string
  + Discount : double
  + IsSent : boolean
}

class InvoiceLine {
  + Amount : double
}

class Payment {
  + Date : date
}

OilCompany "1" -- "*" GasStation
GasStation "1" -- "*" Pump
Pump "1" *-- "1" Reservoir
Pump "1" -- "0..*" RefuelTurn
Pump "1" -- "0..*" CashTurn
Pump "1" -- "0..*" CreditCardTurn

Customer "1" -- "0..*" RefuelTurn
Customer "1" -- "0..*" FuelCard
Customer "1" -- "0..*" Invoice
Customer "1" -- "0..*" Payment

FuelCard "1" -- "0..*" Invoice
Invoice "1" -- "0..*" InvoiceLine
RefuelTurn "1" -- "0..1" InvoiceLine

@enduml

